"""Editorial sample: scoped evidence, measurable proposed criteria, explicit inference."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
sources=[
('clip','Learning Transferable Visual Models From Natural Language Supervision','https://arxiv.org/abs/2103.00020','2021-02-26','Primary paper; abstract checked','Demonstrates zero-shot visual transfer on evaluated datasets. Not universal understanding.'),
('gns','Learning to Simulate Complex Physics with Graph Networks','https://arxiv.org/abs/2002.09405','2020-02-21','Primary paper; abstract checked','Learned particle simulations generalize within evaluated settings. No universal causal engine is established.'),
('af','Highly accurate protein structure prediction with AlphaFold','https://www.nature.com/articles/s41586-021-03819-2','2021-07-15','Primary publisher abstract checked','Strong benchmark protein-structure prediction; accuracy and applicability have limitations.'),
('rt2','RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control','https://arxiv.org/abs/2307.15818','2023-07-28','Primary paper; abstract checked','Transfers web-derived representations to evaluated robot tasks. Does not establish general robot reliability.'),
('diff','Diffusion Policy: Visuomotor Policy Learning via Action Diffusion','https://arxiv.org/abs/2303.04137','2023-03-07','Primary paper; abstract checked','Action diffusion is demonstrated for visuomotor control on selected manipulation tasks.'),
('gnome','Scaling deep learning for materials discovery','https://www.nature.com/articles/s41586-023-06735-9','2023-11-29','Primary publisher abstract checked','Predicts candidate crystal stability. Computation is not synthesis, performance validation, or manufacturability.'),
('alab','An autonomous laboratory for the accelerated synthesis of inorganic materials','https://www.nature.com/articles/s41586-023-06734-w','2023-11-29','Primary publisher abstract checked','Reports an automated inorganic-powder synthesis workflow. Broad autonomous scientific discovery remains a separate claim.'),
('battery','Critical interphase overpotential as a lithium dendrite-suppression criterion','https://www.nature.com/articles/s41560-023-01231-w','2023-04-03','Primary publisher abstract checked','Studies dendrite suppression criteria in solid-state cells; not proof of an industrial battery specification.'),
('osk','Reprogramming to recover youthful epigenetic information and restore vision','https://www.nature.com/articles/s41586-020-2975-4','2020-12-02','Primary publisher abstract checked','Reports retinal-cell reprogramming and functional effects in mice. Does not establish systemic human rejuvenation.'),
('pace','DunedinPACE, a DNA methylation biomarker of the pace of aging','https://elifesciences.org/articles/73420','2022-01-14','Primary publisher abstract checked','Reports a methylation-based pace-of-aging measure trained on longitudinal physiological change; not a validated treatment surrogate.'),
('calerie','Effect of long-term caloric restriction on DNA methylation measures of biological aging','https://www.nature.com/articles/s43587-022-00357-y','2023-02-09','Primary publisher abstract checked','A randomized trial evaluates methylation aging measures. Biomarker movement does not establish longer healthy lifespan.')]
S=[dict(id=a,title=b,url=c,published=d,verification=e,scope=f,checkedAt='2026-10-30') for a,b,c,d,e,f in sources]
N=[]
def node(id,title,domain,stage,status,criterion,uncertainty,src,origin=None,window=None):
 N.append(dict(id=id,title=title,domain=domain,stage=stage,status=status,criteria=criterion,uncertainty=uncertainty,sourceIds=src.split(),sourceEntryIds=origin.split() if origin else [],forecast={'window':window,'basis':'Editorial scenario, not a calibrated forecast. No guaranteed arrival.'} if window else None,routes=[],review='editorial-sample',interpretation='Criteria and relationships are editorial hypotheses. Sources establish only their stated scope.'))
node('AI-01','Transferable visual representations','AI',0,'observed','Demonstrate zero-shot visual classification on held-out benchmark datasets.','Observed scope is benchmark transfer, not general visual common sense.','clip','MLC-03')
node('AI-02','Protein structure prediction','AI',0,'observed','Demonstrate strong accuracy on a blind protein-structure benchmark.','Protein dynamics, interactions and biological utility require additional validation.','af','MLC-09')
node('AI-03','Learned physical simulation','AI',1,'partial','Predict held-out dynamics across new geometries with predefined error bounds and uncertainty calibration.','Published simulations are scoped; broad out-of-distribution reliability remains open.','gns','MLC-06','2027–2032')
node('AI-04','Models that propose testable science','AI',2,'forecast','Produce preregistered novel hypotheses that outperform baselines in independent experiments across three disciplines.','Useful proposals can still fail replication; novelty is hard to assess.','af gnome','MLC-09','2028–2036')
node('AI-05','Reliable experimental planning','AI',3,'forecast','Execute 100 held-out experimental workflows with at least 95% protocol compliance and reported failure recovery.','Operational reliability does not establish general reasoning or open-ended autonomy.','alab gns','MLC-06','2029–2037')
node('AI-06','Closed-loop scientific discovery','AI',4,'forecast','Two independent labs reproduce a new finding from a system that proposed, tested and revised its hypothesis with a logged intervention budget.','Human setup and selection can conceal dependence; discovery quality needs independent review.','alab gnome','MLC-09','2030–2041')
node('ROB-01S','Language-guided robot control','Robotics',0,'partial','Achieve at least 90% success on a preregistered suite of unseen instructions and objects across three sites.','RT-2 demonstrates selected tasks; transfer to new sites is not established by that result.','rt2','ROB-07','2027–2031')
node('ROB-02S','Learned dexterous manipulation','Robotics',1,'partial','Manipulate 50 held-out rigid and deformable objects with at least 90% success and measured recovery.','Benchmark task success is not a universal manipulation principle.','diff','ROB-01','2027–2034')
node('ROB-03S','Risk-bounded shared workspaces','Robotics',2,'forecast','Meet a defined safety case: bounded contact force, fault detection and independent validation across specified operating conditions.','Residual risk remains; no claim of zero injury under arbitrary failures.','rt2 diff','ROB-02','2028–2035')
node('ROB-04S','Skills that transfer between bodies','Robotics',2,'forecast','Transfer 20 held-out skills to three new embodiments with at most 10 demonstrations per skill and report regressions.','Differences in geometry and actuation may require substantial adaptation.','rt2 diff','ROB-04','2029–2036')
node('ROB-05S','Adaptable laboratory robotics','Robotics',3,'forecast','Complete 100 varied preparation and analysis runs with at least 95% completion and traceable contamination checks.','New glassware, materials and hazards can invalidate a trained workflow.','alab diff','ROB-01 ROB-07','2029–2038')
node('ROB-06S','Robots for small-batch production','Robotics',4,'forecast','Operate a changed product line for 1,000 hours with independently measured yield, downtime and human intervention.','Labor economics, maintenance and deployment constraints remain external gates.','rt2 diff','ROB-01 ROB-02','2031–2041')
node('MAT-01S','Candidate crystal prediction','Materials',0,'observed','Predict candidate crystal stability and evaluate it computationally in a documented held-out workflow.','This scoped computational achievement is not experimental verification of every candidate.','gnome','MLC-09')
node('MAT-02S','Automated inorganic synthesis','Materials',1,'partial','Independently reproduce synthesis, phase purity and characterization for 20 preregistered inorganic targets.','Reported autonomous synthesis is evidence of progress; independent broad replication is a separate criterion.','alab','MLC-09','2027–2032')
node('MAT-03S','Properties-first materials discovery','Materials',2,'forecast','Synthesize and independently measure a target property in five new candidates that outperform a preregistered baseline.','Predicted stability does not imply useful properties or scalable processing.','gnome alab','MLC-09','2028–2035')
node('MAT-04S','Stable solid-state battery interfaces','Materials',2,'partial','Demonstrate at least 1,000 cycles at specified temperature, current, pressure and practical areal loading without internal shorting.','Laboratory dendrite suppression may not transfer to practical full cells.','battery','MAS-03','2028–2036')
node('MAT-05S','Manufacturable high-energy cells','Materials',3,'forecast','Produce a pilot batch of 100 full cells exceeding 350 Wh/kg with at least 80% retention after 1,000 cycles and published abuse testing.','These are proposed intermediate targets, not the original absolute-safety promise.','battery','MAS-03','2030–2039')
node('MAT-06S','Longer robot operating time','Materials',4,'forecast','Double useful untethered task time over a documented baseline with comparable payload, mass and safety constraints.','Battery energy is one route; actuation efficiency and duty cycles may dominate.','battery diff','ROB-03','2031–2041')
node('LON-01S','Longitudinal aging measurement','Longevity',0,'observed','Fit and evaluate a methylation-based pace-of-aging measure against longitudinal physiological change.','Observed association does not validate it as a surrogate for treatment benefit.','pace','LON-09')
node('LON-02S','Retinal reprogramming in mice','Longevity',1,'observed','Report retinal-cell reprogramming and improved visual function in the studied mouse setting.','Limited to the reported animal experiments; not a human treatment claim.','osk','LON-05')
node('LON-03S','Validated intervention endpoints','Longevity',2,'partial','Show that treatment-induced biomarker changes predict independently measured functional outcomes in replicated prospective studies.','A clock can move without improving health; validity may be intervention-specific.','pace calerie','LON-09','2028–2036')
node('LON-04S','Tissue-targeted rejuvenation','Longevity',2,'forecast','Replicate sustained functional improvement in a target tissue with lineage tracking and no increased tumors over a predefined follow-up.','Animal retinal effects do not establish other tissues, dosing or long-term safety.','osk','LON-05 LON-07','2029–2038')
node('LON-05S','Human functional benefit trials','Longevity',3,'forecast','A preregistered randomized trial shows clinically meaningful functional improvement with an acceptable predefined safety profile.','Delivery, cancer risk, trial duration and regulatory review remain unresolved gates.','osk calerie','LON-01','2032–2041')
node('LON-06S','Longer measured healthspan','Longevity',4,'forecast','Independent randomized studies demonstrate delayed multi-morbidity or sustained functional health, rather than clock changes alone.','Human follow-up may extend beyond this horizon; systemic aging reversal is not assumed.','calerie pace','LON-01 LON-10','2035–2041+')
D={n['id']:n for n in N}
def route(target,label,all,rationale,uncertainty,src):
 D[target]['routes'].append(dict(id=f'{target}-route-{len(D[target]["routes"])+1}',label=label,all=all.split(),rationale=rationale,uncertainty=uncertainty,sourceIds=src.split(),review='hypothesis'))
route('AI-04','Structure-guided proposals','AI-02','Structural predictions can narrow experimental hypotheses.','Protein structure is only one possible discovery input.','af')
route('AI-04','Materials-guided proposals','MAT-01S','Computed candidates offer experimentally testable hypotheses.','Novel predictions may be unsynthesizable.','gnome')
route('AI-05','Model-assisted planning','AI-03 ROB-05S','Physical models and adaptable manipulation jointly support feedback-controlled experiments.','Other planning architectures may bypass learned simulation; this route is conditional.','gns alab')
route('AI-06','Autonomous experimental loop','AI-04 AI-05 MAT-02S','This proposed route needs proposals, reliable execution and synthesis feedback together.','Automating a workflow alone is insufficient to establish discovery.','alab gnome')
route('ROB-02S','Visuomotor route','AI-01','Transferable representations may support learned manipulation.','Tactile or analytic control could offer other routes.','clip diff')
route('ROB-04S','Transferable control route','ROB-01S ROB-02S','Language conditioning and learned control are candidate ingredients for transferring skills.','Transfer remains dependent on embodiment and training data.','rt2 diff')
route('ROB-05S','Adaptable manipulation route','ROB-02S ROB-03S','Flexible manipulation and a scoped safety case are jointly required for this shared-lab route.','Specialized enclosed instruments could use a different safety route.','alab diff')
route('ROB-06S','Flexible production route','ROB-03S ROB-04S','A proposed shared-workspace production route combines safety validation with transferable skills.','Economics, certification and maintenance are external unresolved prerequisites.','rt2 diff')
route('MAT-03S','Prediction and synthesis loop','MAT-01S MAT-02S','Candidate prediction must be paired with synthesis and measurement in this route.','Property optimization may fail even when crystal stability is predicted correctly.','gnome alab')
route('MAT-05S','Solid-state route','MAT-04S','This solid-state product route requires stable interfaces at practical loading.','Yield, cost and abuse testing remain independent unresolved constraints.','battery')
route('MAT-06S','Higher-energy power source','MAT-05S','Greater pack energy could lengthen a comparable robot duty cycle.','Pack-level mass and thermal limits can erase cell-level gains.','battery')
route('MAT-06S','Efficiency-led route','ROB-04S','Skill transfer could enable more efficient motion planning without a new battery chemistry.','This is a weak hypothesis: transferred skills do not imply energy efficiency; actuator advances are unresolved.','rt2 diff')
route('LON-04S','Partial reprogramming route','LON-02S','The mouse retinal result motivates testing targeted functional restoration elsewhere.','Delivery and tumor surveillance remain explicit unresolved concepts.','osk')
route('LON-05S','Targeted therapy with biomarker support','LON-04S LON-03S','A candidate therapy plus validated endpoints could support trials.','Biomarkers cannot replace clinical outcomes without validation.','osk pace')
route('LON-05S','Direct clinical endpoint route','LON-04S','Trials could measure clinical function directly without a validated aging clock.','Longer, larger studies may be needed.','osk calerie')
route('LON-06S','Long-term clinical validation','LON-05S','Healthspan claims require durable human outcomes beyond early functional results.','Success in one indication does not establish a general longevity effect.','calerie')
A=[]
def accel(a,b,reason,src): A.append(dict(id=f'acc-{len(A)+1}',fromId=a,toId=b,kind='accelerator',rationale=reason,uncertainty='May reduce experimental cost; neither necessary nor sufficient.',sourceIds=src.split()))
accel('AI-02','LON-04S','Structure prediction may assist target selection; it cannot establish rejuvenation.','af osk')
accel('AI-04','MAT-03S','New testable hypotheses may increase candidate throughput.','gnome')
accel('MAT-03S','MAT-04S','Materials screening may surface interface candidates; stability alone is insufficient.','gnome battery')
accel('ROB-05S','LON-03S','Automated assays could increase measurement throughput.','alab pace')
accel('AI-03','ROB-04S','Simulation could reduce the cost of training and testing policies.','gns rt2')
openQuestions=[dict(id='gap-delivery',target='LON-04S',title='Tissue-specific delivery and tumor surveillance',reason='Required for translation but not represented by a verified source entry. No guessed ID substitution.'),dict(id='gap-yield',target='MAT-05S',title='Pilot-line yield, cost and thermal management',reason='Independent engineering constraints; no validated source-ID mapping.'),dict(id='gap-energy',target='MAT-06S',title='Actuator efficiency at matched payload',reason='Efficiency route is a hypothesis; skill transfer alone cannot satisfy this gap.'),dict(id='gap-maintenance',target='ROB-06S',title='Maintenance economics and independent certification',reason='Deployment constraints outside the selected scientific sample.')]
