base=dict(schemaVersion=1,title='TechTree',asOf='2026-10-30',nodes=N,accelerators=A,sources=S,openQuestions=openQuestions)
(root/'research/prototype-before-source-correction/curated.json').write_text(json.dumps(base,ensure_ascii=False,indent=2)+'\n')
